// ---- from Code/GameEngine/Source/Common/System/INI_getNextAsciiString.cpp

// ?getNextAsciiString@INI@@QAE?AVAsciiString@@XZ
AsciiString INI::getNextAsciiString()
{
	AsciiString result;

	const char *token = getNextTokenOrNull(NULL); // if null, just leave an empty string
	if (token != NULL)
	{
		if (token[0] != '\"')
		{
			// if token is simply "
			result.set(token); // Start following the "
		}
		else
		{
			static char buff[1028];
			buff[0] = 0;
			if (strlen(token) > 1)
			{
				_mbscpy(buff, &token[1]);
			}

			token = getNextTokenOrNull(getSepsQuote());
			if (token) {
				if (strlen(token) > 1 && token[1] != '\t')
				{
					_mbscat(buff, " ");
				}
				_mbscat(buff, token);
				result.set(buff);
			} else {
				Int len = strlen(buff);
				if (len && buff[len-1] == '"') { // strip off trailing quote jba. [2/12/2003]
					buff[len-1] = 0;
				}
				result.set(buff);
			}
		}
	}
	return result;
}

// ---- from Code/GameEngine/Source/Common/System/INI_parsePositiveNonZeroReal.cpp

// ?parsePositiveNonZeroReal@INI@@SAXPAV1@PAX1PBX@Z
void INI::parsePositiveNonZeroReal(INI *ini, void *instance, void *store, const void *userData)
{
	float value = ini->scanReal(ini->getNextToken(0));
	*(float *)store = value;
	if (value <= 0.0f) {
		throw INIException(3, "invalid Real value %1.7f -- expected > 0", value);
	}
}

